import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Evidence","description":"","frontmatter":{},"headers":[],"relativePath":"learner/evidence.md","filePath":"learner/evidence.md"}'),g={name:"learner/evidence.md"};function c(o,n,u,e,r,l){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h1><p>Trên trang này# Evidence <a href="#evidence">​</a> Evidence là một quan sát cụ thể về việc learner đã làm gì — càng gần sự thật thô càng tốt, và <strong>không kèm kết luận nào</strong>. Không phải evidence&quot;Yếu đại số.&quot;&quot;Không tập trung.&quot;&quot;Học chậm hơn các bạn.&quot; Đây là những diễn giải. Chúng đã đóng gói sẵn một phán xét, và không ai biết chúng dựa trên cái gì. Là evidence&quot;Ngày 3/9, sai 4/5 câu phân tích đa thức, trung bình 3 phút 20 giây mỗi câu, dùng gợi ý ở 3 câu, tự khai mức tự tin 2/4.&quot; Đây là quan sát. Nó không hết hạn, và mọi kết luận rút ra từ nó đều tính lại được.</p><h2 id="vi-sao-ranh-gioi-nay-quan-trong-đen-vay-​" tabindex="-1">Vì sao ranh giới này quan trọng đến vậy <a href="#vi-sao-ranh-gioi-nay-quan-trong-đen-vay">​</a> <a class="header-anchor" href="#vi-sao-ranh-gioi-nay-quan-trong-đen-vay-​" aria-label="Permalink to &quot;Vì sao ranh giới này quan trọng đến vậy [​](#vi-sao-ranh-gioi-nay-quan-trong-đen-vay)&quot;">​</a></h2><p>Ba lý do, và cả ba đều có hệ quả thực tế với gia đình bạn. <strong>Kết luận có thể sai, quan sát thì không.</strong> Nếu cách đánh giá của hệ thống được cải tiến, mọi kết luận cũ tính lại được từ dữ liệu gốc. Nếu hệ thống chỉ lưu nhãn &quot;yếu đại số&quot;, cái nhãn đó mắc kẹt vĩnh viễn ở mức hiểu biết của ngày nó được tạo ra. <strong>Nhãn dán bám vào đứa trẻ.</strong> &quot;Học chậm&quot; được ghi năm lớp 6 sẽ đi theo một đứa trẻ suốt nhiều năm, kể cả khi nó đã sai từ lâu. Còn &quot;ngày 3/9 mất 3 phút 20 giây mỗi câu&quot; thì tự nó mờ đi khi có quan sát mới hơn — nó không có sức sống của một nhãn dán. <strong>Bạn có quyền hỏi &quot;dựa vào đâu&quot;.</strong> Vì hệ thống lưu quan sát, nó luôn trả lời được. Không có kết luận nào của Nemo12 mà không truy ngược được về những sự kiện cụ thể sinh ra nó.</p><h2 id="trong-mot-mau-evidence-co-gi-​" tabindex="-1">Trong một mẩu evidence có gì <a href="#trong-mot-mau-evidence-co-gi">​</a> <a class="header-anchor" href="#trong-mot-mau-evidence-co-gi-​" aria-label="Permalink to &quot;Trong một mẩu evidence có gì [​](#trong-mot-mau-evidence-co-gi)&quot;">​</a></h2><p>textEvidence ├── learner nào ├── nguồn — bài luyện tập / bài đo / thầy cô / mentor / phụ huynh / learner tự khai ├── loại — trả lời đúng-sai, thời gian, dùng gợi ý, tự đánh giá… ├── nhắm vào — mảng kiến thức nào ├── giá trị — kết quả quan sát được ├── thời điểm ├── độ tin cậy — nguồn này tin được tới đâu └── ngữ cảnh — lúc đó đang có chuyện gì (ốm? sắp thi?)</p><h2 id="khong-phai-nguon-nao-cung-nang-nhu-nhau-​" tabindex="-1">Không phải nguồn nào cũng nặng như nhau <a href="#khong-phai-nguon-nao-cung-nang-nhu-nhau">​</a> <a class="header-anchor" href="#khong-phai-nguon-nao-cung-nang-nhu-nhau-​" aria-label="Permalink to &quot;Không phải nguồn nào cũng nặng như nhau [​](#khong-phai-nguon-nao-cung-nang-nhu-nhau)&quot;">​</a></h2><p>NguồnĐộ tin cậy khởi điểmBài đo chuẩn hoá0.95Nhận xét của giáo viên0.85Bài luyện tập trong hệ thống0.80Quan sát của mentor0.75Quan sát của phụ huynh0.60Learner tự khai0.50Những con số này là <strong>điểm khởi đầu</strong>, không cố định. Nếu quan sát của một phụ huynh liên tục khớp với kết quả đo về sau, trọng số của nguồn đó tăng lên theo thời gian. Điều đáng nói: quan sát của phụ huynh có mặt trong danh sách này. Bạn nhìn thấy những thứ hệ thống không bao giờ thấy — con nản ở đâu, con hào hứng chỗ nào, con làm bài tập lúc mấy giờ. Đó là bằng chứng thật, chỉ là loại bằng chứng cần đọc thận trọng hơn một bài đo.</p><h2 id="bang-chung-đa-ghi-thi-khong-sua-khong-xoa-​" tabindex="-1">Bằng chứng đã ghi thì không sửa, không xoá <a href="#bang-chung-đa-ghi-thi-khong-sua-khong-xoa">​</a> <a class="header-anchor" href="#bang-chung-đa-ghi-thi-khong-sua-khong-xoa-​" aria-label="Permalink to &quot;Bằng chứng đã ghi thì không sửa, không xoá [​](#bang-chung-đa-ghi-thi-khong-sua-khong-xoa)&quot;">​</a></h2><p>Nếu một mẩu evidence sai — ghi nhầm, hoặc hoá ra learner làm bài hộ ai đó — hệ thống <strong>ghi thêm một mẩu mới thay thế nó</strong>, chứ không sửa đè. Lịch sử giữ nguyên vẹn. Nghe có vẻ nệ nguyên tắc, nhưng nó là điều kiện để mọi kết luận đều giải thích được. Một hệ thống tự sửa quá khứ của mình thì không còn giải thích được hiện tại.</p><h2 id="tra-loi-đung-chua-chac-đa-la-bang-chung-cua-viec-biet-​" tabindex="-1">Trả lời đúng chưa chắc đã là bằng chứng của việc biết <a href="#tra-loi-đung-chua-chac-đa-la-bang-chung-cua-viec-biet">​</a> <a class="header-anchor" href="#tra-loi-đung-chua-chac-đa-la-bang-chung-cua-viec-biet-​" aria-label="Permalink to &quot;Trả lời đúng chưa chắc đã là bằng chứng của việc biết [​](#tra-loi-đung-chua-chac-đa-la-bang-chung-cua-viec-biet)&quot;">​</a></h2><p>Nemo12 không tính mọi câu đúng như nhau. Cùng một câu trả lời đúng có thể mang sức nặng rất khác:</p><ul><li>Đúng sau 2 giây ở bài cần 90 giây → nhiều khả năng là đoán, gần như không được tính.</li><li>Đúng nhưng có gợi ý → bằng chứng của &quot;làm được khi có người đỡ&quot;, nhẹ hơn.</li><li>Đúng, tự làm, đúng thời gian dự kiến, khai chắc chắn → bằng chứng mạnh.</li><li>Đúng trong một bài trộn lẫn nhiều dạng, sau vài tuần không đụng tới → bằng chứng mạnh nhất. Và ngược lại, <strong>nút &quot;Chưa biết&quot; được coi là một tín hiệu trung thực có giá trị</strong> — nó nói rõ hơn về learner so với một câu đoán bừa mà may mắn đúng. Điều này bảo vệ con bạn Một đứa trẻ mệt, bấm bừa cho xong 10 câu, sẽ không bị hệ thống kết luận là &quot;yếu&quot;. Phiên đó được đánh dấu <strong>không đủ dữ liệu tin cậy</strong> và hẹn đo lại vào lúc khác. Hình phạt cho việc mệt không nên là bị bắt học lại thứ mình đã biết. Quan sát là thứ đáng lưu. Kết luận là thứ nên tính lại được bất cứ lúc nào. <a href="/learner/confidence">Confidence Score →</a></li></ul>',13)])])}const k=h(g,[["render",c]]);export{m as __pageData,k as default};
